'use strict';
const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
$('#menu').addEventListener('click',()=>{const open=$('#indice').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open));});
function closeMenu(){$('#indice').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');}
$$('#indice a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('click',e=>{if(!e.target.closest('#indice')&&!e.target.closest('#menu'))closeMenu();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});
const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){$$('#indice a').forEach(a=>a.classList.toggle('current',a.hash==='#'+e.target.id));}});},{rootMargin:'-20% 0px -60% 0px'});
$$('main section[id]').forEach(s=>observer.observe(s));
function progress(){const d=document.documentElement;$('.progress').style.width=(d.scrollHeight>d.clientHeight?100*d.scrollTop/(d.scrollHeight-d.clientHeight):0)+'%';}window.addEventListener('scroll',progress,{passive:true});progress();
if(window.gsap&&!reduced){gsap.from('.hero-copy > *',{y:22,opacity:0,duration:.85,stagger:.1,ease:'power2.out'});gsap.from('.hero-visual',{opacity:0,y:25,duration:1,delay:.25});const reveal=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){gsap.from(e.target,{y:22,opacity:0,duration:.7,ease:'power2.out'});reveal.unobserve(e.target);}});},{threshold:.1});$$('.section-head,.origin-top,.voice,.caption-row').forEach(e=>reveal.observe(e));}
const logos={principal:{type:'IMAGOTIPO PRINCIPAL',title:'Una ventana al origen.',description:'Símbolo de montaña y sol dentro de un arco, acompañado del nombre AMPA Café. Sus elementos pueden funcionar por separado cuando el contexto permite reconocer la marca.'},alternativo:{type:'FIRMA ALTERNATIVA',title:'El paisaje dentro del nombre.',description:'Logotipo con las montañas integradas en la M. Una composición más horizontal que conserva el homenaje familiar y conecta el nombre con el territorio.'}};
$$('[data-logo]').forEach(b=>b.addEventListener('click',()=>{const k=b.dataset.logo,d=logos[k];$$('[data-logo]').forEach(t=>t.setAttribute('aria-selected',String(t===b)));$('#logo-preview').src='assets/logo-'+k+'.webp';$('#logo-preview').alt='Firma '+k+' de AMPA Café';$('#logo-type').textContent=d.type;$('#logo-title').textContent=d.title;$('#logo-description').textContent=d.description;$('#logo-download').href='assets/logo-'+k+'.webp';$('#logo-panel').setAttribute('aria-labelledby',b.id);}));
$$('[role=tab]').forEach((b,i)=>b.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();const next=$$('[role=tab]')[1-i];next.focus();next.click();}}));
$$('.filter').forEach(b=>b.addEventListener('click',()=>{const f=b.dataset.filter;$$('.filter').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});let count=0;$$('.gallery-item').forEach(card=>{card.hidden=f!=='Todas'&&card.dataset.category!==f;if(!card.hidden)count++;});$('#gallery-count').textContent=count+(count===1?' aplicación':' aplicaciones');}));
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2800);}
$$('[data-copy]').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);toast('Color copiado: '+b.dataset.copy);}catch{toast('Código del color: '+b.dataset.copy);}}));
const modal=$('#lightbox');let trigger;
$$('[data-image]').forEach(b=>b.addEventListener('click',()=>{trigger=b;$('#modal-title').textContent=b.dataset.title;$('#modal-image').src=b.dataset.image;$('#modal-image').alt=b.dataset.title;$('#modal-download').href=b.dataset.image;$('#modal-download').download=b.dataset.image.split('/').pop();modal.showModal();document.body.style.overflow='hidden';$('#close-modal').focus();}));
function closeModal(){modal.close();}$('#close-modal').addEventListener('click',closeModal);modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});modal.addEventListener('close',()=>{document.body.style.overflow='';trigger?.focus();});
let printDetails=[];window.addEventListener('beforeprint',()=>{printDetails=$$('details').map(d=>d.open);$$('details').forEach(d=>d.open=true);});window.addEventListener('afterprint',()=>{$$('details').forEach((d,i)=>d.open=printDetails[i]);});
['#print','#print-bottom'].forEach(s=>$(s).addEventListener('click',()=>window.print()));
